fs.writeFileSync(script,`import assert from 'node:assert/strict';import fs from 'node:fs';import {pathToFileURL} from 'node:url';const root=process.cwd(),{build}=await import(pathToFileURL(root+'/scripts/workspace-test-build.mjs')),{exactSourceHistoryApi}=await import(pathToFileURL(root+'/scripts/exact-source-history-api.mjs'));const before=await exactSourceHistoryApi('665c53a4d21667d14f12cf2e81a200d5da3df3ac','review-security');const built=await build({stdin:{contents:"export * from './lib/body-review-material';export * from './lib/body-review-context';export * from './lib/body-review-response';",resolveDir:root,loader:'ts'},bundle:true,write:false,platform:'node',format:'esm'});const after=await import('data:text/javascript;base64,'+Buffer.from(built.outputFiles[0].text).toString('base64'));const pins=JSON.parse(fs.readFileSync(root+'/content/abdominal-branch-imaging-pins.json')),fmas=new Set(['FMA14805','FMA14784','FMA14826','FMA14824']),selected=pins.entries.filter(r=>fmas.has(r.identity.fmaId));assert.equal(selected.length,4);let stale=0,forged=0;for(const {identity:s}of selected){const prior=await before.bodyReviewMaterial(s.id),current=await after.bodyReviewMaterial(s.id);assert(prior&&current);assert.equal(current.approval,false);assert.equal(prior.topics.find(t=>t.tab==='ultrasound').readiness,'pending');assert.equal(current.topics.find(t=>t.tab==='ultrasound').readiness,'draft');for(const key of ['source','reasoning','guidedTours','checklist','atlasLink','limits'])assert.deepEqual(current[key],prior[key],s.id+':'+key);assert.equal(current.fingerprints.source,prior.fingerprints.source);assert.notEqual(current.fingerprints.teaching,prior.fingerprints.teaching);assert.notEqual(current.materialHash,prior.materialHash);assert.deepEqual(await after.parseBodyReviewResponse(current,s.id),current);assert.equal(await after.parseBodyReviewResponse(prior,s.id),null);stale++;for(const change of [v=>{v.topics.find(t=>t.tab==='ultrasound').body+=' foreign';},v=>{v.topics.find(t=>t.tab==='ultrasound').citations=['https://example.invalid/foreign'];},v=>{v.topics.find(t=>t.tab==='ultrasound').readiness='approved';}]){const changed=structuredClone(current);change(changed);assert.equal(await after.parseBodyReviewResponse(changed,s.id),null);forged++;}}console.log(JSON.stringify({actualBeforeCommit:'665c53a4d21667d14f12cf2e81a200d5da3df3ac',selected:4,stalePacketsRefused:stale,forgedPacketsRefused:forged,sourceReasoningToursAndClinicalChecklistUnchanged:true,privateRecordsReadOrMigrated:false,clinicalApproval:false}));`,{flag:'wx'});global.gc();const run=await guarded({site:prep.atlas,dir,command:'--max-old-space-size=1024 '+script,heap:1024,aggregate:2048,minimum:4096});verify();let assertions=null;if(run.passing){assertions=json(dir+'/runner.stdout.log');assert.equal(assertions.stalePacketsRefused,4);assert.equal(assertions.forgedPacketsRefused,12);}const result={at:new Date().toISOString(),passing:run.passing,run,assertions,program:{path:script,sha256:hash(script)},actualCommittedParentAndActualWorkingSource:true,noSourceOverridesOrMockExports:true,privateRecordsReadOrMigrated:false,ownerPreviewChanged:false,clinicalApproval:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),passing:run.passing,assertions}));process.exitCode=run.passing?0:1;
